import { Database } from 'bun:sqlite';

const db = new Database('app.db');

interface Counter {
  id: string;
  value: number;
}

async function incrementCounter(counterId: string): Promise<number> {
  const row = db.query('SELECT value FROM counters WHERE id = ?').get(counterId) as Counter | null;

  if (!row) {
    db.run('INSERT INTO counters (id, value) VALUES (?, 1)', counterId);
    return 1;
  }

  const newValue = row.value + 1;
  db.run('UPDATE counters SET value = ? WHERE id = ?', newValue, counterId);
  return newValue;
}

// Called from multiple concurrent HTTP handlers
export async function handleRequest(req: Request): Promise<Response> {
  const counterId = new URL(req.url).searchParams.get('id') ?? 'default';
  const value = await incrementCounter(counterId);
  return new Response(JSON.stringify({ value }));
}
